// Uma entrada da API Graph contém o array value.
const pages = $input.all();
const out = [];
for (const page of pages) {
  for (const item of (page.json.value || [])) {
    const f = item.fields || {};
    const chave = String(f.CHAVE_NFE || '').trim();
    if (!/^\d{44}$/.test(chave)) continue;
    if (String(f.STATUS_INTEGRACAO || '').trim().toUpperCase() !== 'INTEGRADO') continue;
    out.push({json: {item_id: String(item.id), chave_nfe: chave}});
  }
}
return out;

// 05 - ATUALIZAR APENAS CAMPOS ALTERADOS (FLUXO 02)
// Compara retorno SQL com valores atuais do SharePoint (node 02).
// Nao sobrescreve valores existentes com NULL.
const sql = $input.all();
const pages = $('02 - Ler lista SharePoint').all();
const pendentes = $('03 - Separar NFs integradas').all();
const norm = v => v === undefined || v === null ? '' : String(v).trim();
const spPorId = new Map();
for (const page of pages) {
  for (const item of (page.json.value || [])) {
    spPorId.set(norm(item.id), item.fields || {});
  }
}
const idPorChave = new Map();
for (const item of pendentes) {
  const chave = norm(item.json.chave_nfe);
  if (!/^\d{44}$/.test(chave)) throw new Error('CHAVE_NFE invalida');
  if (idPorChave.has(chave)) throw new Error('CHAVE_NFE duplicada no SharePoint: ' + chave);
  idPorChave.set(chave, norm(item.json.item_id));
}
// Compara instantes com fuso caso informados como ISO; nao converte
// horario SQL como se fosse UTC diferente. Confirmar UTC x BRT antes de ativar.
function normalizeDate(value, dateOnly) {
  if (value === null || value === undefined || value === '') return null;
  const v = String(value).trim();
  if (!/^\d{4}-\d{2}-\d{2}(?:T|$)/.test(v)) throw new Error('Data invalida: '+v);
  return dateOnly ? v.slice(0,10) : v;
}
function sameDate(a,b,dateOnly) {
  if (dateOnly) return norm(a).slice(0,10) === norm(b).slice(0,10);
  const x=Date.parse(String(a)), y=Date.parse(String(b));
  if (!Number.isNaN(x) && !Number.isNaN(y)) return Math.abs(x-y)<1000;
  return norm(a)===norm(b);
}
const output = [];
const visto = new Set();
for (const item of sql) {
  const d=item.json;
  const chave=norm(d.CHAVE_NFE);
  const id=idPorChave.get(chave);
  if (!id) throw new Error('SQL retornou CHAVE_NFE sem correspondente no SharePoint: '+chave);
  if (visto.has(chave)) throw new Error('SQL retornou CHAVE_NFE duplicada: '+chave);
  visto.add(chave);
  const atual=spPorId.get(id);
  if (!atual) throw new Error('ID nao encontrado nos registros lidos: '+id);
  const alteracoes={};
  function setText(nome,valor) {
    const novo=norm(valor); // nao apagar campos com valor NULL/vazio
    if (novo && novo!==norm(atual[nome])) alteracoes[nome]=novo;
  }
  function setDate(nome,valor,soData=false) {
    const novo=normalizeDate(valor,soData);
    if (novo && !sameDate(novo,atual[nome],soData)) alteracoes[nome]=novo;
  }
  setDate('DATA_AGENDAMENTO', d.DATA_AGENDAMENTO);
  setDate('INICIO_CONFERENCIA_SUL', d.INICIO_CONFERENCIA_SUL);
  setDate('FIM_CONFERENCIA_SUL', d.FIM_CONFERENCIA_SUL);
  setText('ROMANEIO', d.ROMANEIO);
  setText('TRANSPORTADORA', d.TRANSPORTADORA);
  setText('PLACA', d.PLACA);
  setText('MOTORISTA', d.MOTORISTA);
  setDate('DATA_EMBARQUE', d.DATA_EMBARQUE);
  setDate('PREVISAO_CHEGADA', d.PREVISAO_CHEGADA, true);
  // Sem mudancas = sem requisicao PATCH, preservando versao e historico.
  if (!Object.keys(alteracoes).length) continue;
  output.push({json:{item_id:id,chave_nfe:chave,fields:alteracoes,campos_alterados:Object.keys(alteracoes)}});
}
return output;
